// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz: an address for `from` and a uint v; we will deploy a Reverter helper and pass its address
    // as caddress, and a single-element _tos array containing an arbitrary recipient addr.
    function testFuzz_property(address from, address recipient, uint256 v) public {
        // keep recipient non-zero and from non-zero to be within admissible domain
        vm.assume(recipient != address(0));
        vm.assume(from != address(0));
        // Deploy a callee that will revert on the transferFrom selector
        Reverter reverter = new Reverter();

        address[] memory tos = new address[](1);
        tos[0] = recipient;

        // Call c.transfer and observe whether it reverts. The reference implementation requires
        // that the external call success is checked, so when the callee reverts the whole
        // transfer() should revert; the mutant (which ignores the success flag) will NOT revert
        // and will return true. We capture that difference via try/catch and assert that the
        // call DID revert (i.e., ok==false) for ALL inputs — the reference satisfies this, the
        // mutant will fail for the case where the callee reverts.

        bool ok;
        try c.transfer(from, address(reverter), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for any admissible inputs (non-empty tos we ensure by building one),
        // when the callee reverts, the correct contract propagates the revert (ok == false).
        // The mutant that drops the require will return true (ok == true) for some inputs, causing this test to fail.
        assertTrue(!ok);
    }
}

// adversarial helper that reverts whenever called with the transferFrom selector
contract Reverter {
    // declare the function matching selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address, address, uint256) external payable {
        revert("revert in callee");
    }

    // also protect against direct calls to fallback
    fallback() external payable {
        revert("revert fallback");
    }
    receive() external payable {
        revert("revert receive");
    }
}
